using Capability39.Cooperation;
using static Capability39.Cooperation.ParallelEvidence46;
int checks=0;void Check(bool x){if(!x)throw new Exception("check failed");checks++;}void Reject(Action a){try{a();}catch(Exception e)when(e is InvalidOperationException or ArgumentException){checks++;return;}throw new Exception("expected rejection");}
var w=Guid.NewGuid();var a=new ParallelSample46(new(w,Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid()),Guid.NewGuid(),0,"running",new(0,0,0));var b=new ParallelSample46(new(w,Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid()),Guid.NewGuid(),0,"running",new(0,0,2));
ParallelPair46 Pair(double t,double x)=>new(a with{GameTime=t,Position=new(x,0,0)},b with{GameTime=t,Position=new(x,0,2)});
var samples=new[]{Pair(0,0),Pair(.5,.5),Pair(1,1)};var r=ValidateRunningWindow(samples);Check(r.Samples==3);Check(r.ObservedSpanSeconds==1);Check(r.MaximumSampleGapSeconds==.5);Check(!r.ContinuousCoverageProven);Check(r.DisplacementA==1&&r.DisplacementB==1);
