var before=Pair(1,1);var after=Pair(1.1,1.1);after=after with{A=after.A with{Status="cancelled"}};var fa=after.A with{GameTime=2};var fb=b with{GameTime=2,Position=new(2,0,2),Status="succeeded"};
ValidateCancellationIsolation(before,after,fb,fa);checks++;
Reject(()=>ValidateCancellationIsolation(before,after with{B=after.B with{Status="cancelled"}},fb,fa));Reject(()=>ValidateCancellationIsolation(before,after,fb with{RunId=Guid.NewGuid()},fa));Reject(()=>ValidateCancellationIsolation(before,after,fb,fa with{Status="running"}));Reject(()=>ValidateCancellationIsolation(before,after,fb,fa with{Position=new(2,0,0)}));Reject(()=>ValidateCancellationIsolation(before,after,fb with{Position=after.B.Position},fa));Reject(()=>ValidateCancellationIsolation(before,after,fb with{GameTime=1.1},fa with{GameTime=1.1}));Reject(()=>ValidateCancellationIsolation(before,after,fb,fa with{GameTime=3}));
